param([Parameter(Mandatory=$true)][string]$CheckRoot,[Parameter(Mandatory=$true)][string]$BenchmarkRoot)
$ErrorActionPreference='Stop'
$taskProject=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$taskJar="$taskProject/build/libs/WitherSkyRU-26.1.2-fabric-0.15.69-dev.jar";$taskHash=(Get-FileHash -LiteralPath $taskJar).Hash
$taskScope=Get-Content "$CheckRoot/CHECK_SCOPE.json" -Raw|ConvertFrom-Json
$taskAudit=Get-Content "$taskProject/translation-source/HUB_NPC_AUDIT_0.15.69.json" -Raw|ConvertFrom-Json
$taskJarScope=Get-Content "$taskProject/translation-source/JAR_SCOPE_0.15.69.json" -Raw|ConvertFrom-Json
$taskBenchScope=Get-Content "$BenchmarkRoot/SCOPE.json" -Raw|ConvertFrom-Json
$taskRecheck=Get-Content "$taskProject/translation-source/PERFORMANCE_0.15.69_RECHECK.json" -Raw|ConvertFrom-Json
if($taskScope.targeted_only -or $taskScope.tests_passed.Count -ne 120 -or @($taskScope.tests_passed|Sort-Object -Unique).Count -ne 120 -or $taskScope.runtime_jar_sha256 -ne $taskHash -or $taskJarScope.jar_sha256 -ne $taskHash -or $taskAudit.jar_sha256 -ne $taskHash -or $taskBenchScope.jar_sha256 -ne $taskHash -or $taskRecheck.jar_sha256 -ne $taskHash -or $taskRecheck.results.Count -ne 3){throw 'Different or incomplete final executable evidence'}
if($taskAudit.catalogue_changed_record_ids.Count -ne 0 -or $taskAudit.catalogue_cards_compared -ne 8937 -or $taskAudit.after.unchanged -ne 0 -or $taskAudit.after.changed_not_complete -ne 79){throw 'Unexpected replay/catalogue difference'}
$taskRaw=@();$taskTable=@();$taskFlags=@()
foreach($taskMode in $taskBenchScope.modes){$taskRuns=@();for($taskIndex=0;$taskIndex -lt 4;$taskIndex++){$taskVersion=if($taskIndex -in @(0,3)){'0.15.68-dev'}else{'0.15.69-dev'};$taskPath="$BenchmarkRoot/$taskMode-$taskIndex-$taskVersion.json";$taskRun=Get-Content -LiteralPath $taskPath -Raw|ConvertFrom-Json;if($taskRun.$taskMode.rounds_ms.Count -ne 4 -or $taskRun.$taskMode.rounds_bytes.Count -ne 4){throw 'Missing raw rounds'};$taskRuns+=,$taskRun}
 $taskOld=@($taskRuns[0].$taskMode,$taskRuns[3].$taskMode);$taskNew=@($taskRuns[1].$taskMode,$taskRuns[2].$taskMode)
 $taskCpu=@((100*($taskNew[0].ms_per10/$taskOld[0].ms_per10-1)),(100*($taskNew[1].ms_per10/$taskOld[1].ms_per10-1)))
 $taskAlloc=@((100*($taskNew[0].bytes_per10/$taskOld[0].bytes_per10-1)),(100*($taskNew[1].bytes_per10/$taskOld[1].bytes_per10-1)))
 $taskRow=@{mode=$taskMode;cpu_percent=$taskCpu;allocation_percent=$taskAlloc;before_microseconds_per_input=@($taskOld|ForEach-Object {$_.ms_per10*100});after_microseconds_per_input=@($taskNew|ForEach-Object {$_.ms_per10*100});equal_useful_output_work=($taskMode -notin @('world_new_roles','npc_new'))}
 $taskTable+=,$taskRow;$taskRaw+=@{mode=$taskMode;runs=$taskRuns}
 if($taskCpu[0] -gt 10 -and $taskCpu[1] -gt 10){$taskFlags+=,$taskRow}
}
$taskPerformance=@{date='2026-10-15';scope=$taskBenchScope.scope;jar_sha256=$taskHash;baseline_sha256=$taskBenchScope.baseline_sha256;benchmark_root=$BenchmarkRoot;all_timing_and_allocation_rounds_retained=$true;results=$taskTable;raw=$taskRaw;over10percent_cpu_increase_both_orders=$taskFlags;actual_game_fps_measured=$false;zero_fps_impact_proven=$false}
[IO.File]::WriteAllText("$taskProject/translation-source/PERFORMANCE_0.15.69_RAW.json",($taskPerformance|ConvertTo-Json -Depth 20)+"`n",[Text.UTF8Encoding]::new($false))
$taskInvariant=[Globalization.CultureInfo]::InvariantCulture
function Fmt69($n){return ([double]$n).ToString('0.000',$taskInvariant)}
$taskLines=@('# WitherSkyRU 0.15.69-dev — NPC, проверенная партия','', 'Дата: 2026-10-15. Minecraft 26.1.2 / Fabric.','', '## Результат','', 'Добавлены 83 точные реплики для 20 персонажей: 53 наблюдавшихся исходных текста и 30 опубликованных вариантов. Две дополнительные числовые формы Филлипа сохраняют исходные значения, знаки, цвета и действия каждого числового символа. Четыре подписи ответов Максвеллу, пять отдельных мировых надписей.','', 'У Максвелла проверены все восемь наблюдавшихся реплик вступления и три наблюдавшиеся кнопки ответа. ACCESSORY POWER переведено как «сила аксессуаров». Старые MAGICAL POWER и формула Math Enjoyer поддерживаются только как точные опубликованные варианты, а не доказательство актуальности старой механики.','', 'Имена NPC в префиксе чата сохраняются: это позволяет находить персонажей в английских справочниках и не затрагивать игроков. Роли Thaumaturgist, Maths Enjoyer, Enchantment Nerd и ENCHANTMENT GUIDE переведены в мировых надписях. CLICK — только как отдельная надпись над неигровой сущностью. Имена игроков, неизвестные сущности, подписанный и обычный пользовательский чат не переводятся.','', '## Таблица этой партии','', '| Персонаж | Новых точных строк | Из них наблюдались | Только опубликованные варианты |','|---|---:|---:|---:|')
foreach($taskRow in $taskAudit.batch){$taskLines+="| $($taskRow.speaker) | $($taskRow.new_exact_lines) | $($taskRow.observed_source_bodies) | $($taskRow.published_only_variants) |"}
$taskLines+=@('','У Филлипа дополнительно две числовые формы. Таблица не является перечнем всех реплик этих NPC.','', '## Проверка наблюдавшихся сообщений','', '| Конечный набор | Версия 68 | Версия 69 |','|---|---:|---:|','| Без изменения видимого текста | 66 | 0 |','| С изменением видимого текста | 13 | 79 |','', '79 — число отобранных вариантов сообщений, включая повторы со счётчиком. Само изменение строки не доказывает качество перевода. Для 53 новых исходных текстов отдельный тест сверяет независимые игровые образцы с вычитанными целями; ещё две наблюдавшиеся числовые реплики проверяются отдельно. В текстах оставлен /party как реальная команда, без её выполнения.','', '## Ограничения полноты','', "В ресурсах сейчас $($taskAudit.known_exact_speakers.Count) отдельных имён говорящих. Это не полный список NPC сервера и не число полностью переведённых сюжетных веток. Общее количество всех актуальных серверных реплик неизвестно, поэтому честное число «осталось перевести» для всего Hypixel пока недоступно.",'', 'Не объявляются завершёнными: все ответы Максвелла с обращением к имени игрока, все неподтверждённые современные варианты его Абифона, полное обучение у Enchantment Nerd и все ветви остальных NPC. Список учтённых говорящих и источников находится в HUB_NPC_AUDIT_0.15.69.json.','', '## Проверки','', '120 отдельных групп завершены на одном финальном JAR. Девять целевых успешных процессов перенесены из предварительного целевого прогона с тем же SHA256; остальные 111 выполнены в полном прогоне. Исходный корень и названия сохранены в CHECK_SCOPE.json. Новый независимый тест: 80 809 утверждений. Старый дифференциальный тест восьми поставщиков NPC сохранён; старые 476 сюжетных реплик не удалены.','', 'Все 8 937 карточек предметов сравнены с проверенной версией 68: ноль различий полного результата. Существующие старые неполные переводы предметов этим не исправлены и не объявлены готовыми.','', 'Предварительная сборка B4F8B8F4 прошла автоматические тесты, но отклонена дополнительной проверкой: глобальный CLICK менял восемь карточек. Она сохранена только в build/prototypes и не поставляется. В финальной версии замена ограничена мировым обработчиком.','', '## Оптимизация','', 'Новые точные строки объединяются с прежним поиском при запуске. Девятого прохода сообщений, новых кадровых перехватов, новых кэшей и сетевых обращений нет. Прежний обработчик мировых надписей получил конечный список ролей; CLICK отдельно проверяет только текущий буквальный текст и единый стиль. Стиль и готовый Component не кэшируются между кадрами.','', 'Байты обработчиков кадров, RenderContext, OfflineDictionary, старых кэшей, StyledRuns, StyledItemTitle, ReviewedLore и TooltipTranslation совпадают с версией 68. Изменения основного клиента относятся к мировому списку и новому помощнику надписи.','', '28 отдельных процессов: порядок 68 → 69 → 69 → 68 для каждого из семи сценариев. В каждом процессе 20 000 прогревочных пакетов и четыре раунда по 4 000 пакетов. В пакете десять входных строк. Сохранены все раунды времени и выделения памяти. Это микротесты текстового API, не игровой FPS, отрисовка шрифтов, мира или работа GPU.','', '| Сценарий | Изменение времени, два порядка | Версия 69, мкс на вход |','|---|---:|---:|')
foreach($taskRow in $taskTable){$taskLines+="| $($taskRow.mode) | $(Fmt69 $taskRow.cpu_percent[0])% / $(Fmt69 $taskRow.cpu_percent[1])% | $(Fmt69 $taskRow.after_microseconds_per_input[0]) / $(Fmt69 $taskRow.after_microseconds_per_input[1]) |"}
$taskLines+=@('','world_new_roles и npc_new делают дополнительный полезный перевод, которого нет в версии 68: это не сравнение равной работы. Для остальных сценариев текстовый результат одинаков. Проценты микротестов нельзя переводить в проценты потери FPS.', '', "Сценариев с увеличением времени более 10% в обоих порядках: $($taskFlags.Count). Полные результаты и флаги, без удаления неудобных раундов: PERFORMANCE_0.15.69_RAW.json.",'', 'Игровой FPS версии 69 ещё не измерен. Нулевое влияние на FPS не доказано. Установленная сборка игры не менялась, игра не запускалась и не перезапускалась.','', '## Источники','', '- Скриншот пользователя codex-clipboard-eddba8a8-d15e-4a57-b861-13940cfb7988.png и строго отобранные публичные строки NPC из игровых записей: HUB_NPC_OBSERVED_0.15.69.json. Полные журналы, пользовательский чат и личные обращения не включены.','- [Maxwell — опубликованные варианты](https://hypixel-skyblock.fandom.com/wiki/Maxwell). Наблюдавшиеся текущие реплики важнее старых терминов страницы.','- [Jacobus — индексировавшиеся точные цитаты](https://wiki.hypixel.net/Jacobus). Старая официальная страница теперь перенаправляет на объявление о закрытии; это не живое подтверждение всех современных реплик.','- [Maths Enjoyer — опубликованные точные реплики](https://hypixel-skyblock.fandom.com/wiki/Maths_Enjoyer). Актуальность всей формулы в игре не установлена.','', '## Файл','', "JAR: $([IO.Path]::GetFileName($taskJar))", "SHA256: $taskHash", "Размер: $((Get-Item -LiteralPath $taskJar).Length) байт.")
$taskLines+=@('','## Повтор мировых сценариев','', 'Дополнительно выполнены 12 отдельных процессов с увеличенным прогревом: 100 000 пакетов и четыре раунда по 20 000 пакетов. Повторены все три мировых сценария с одинаковым полезным результатом. Исходный первый прогон не удалён.','', '| Сценарий | Изменение времени, два порядка | Версия 69, мкс на вход |','|---|---:|---:|')
foreach($taskRow in $taskRecheck.results){$taskLines+="| $($taskRow.mode) | $(Fmt69 $taskRow.cpu_percent[0])% / $(Fmt69 $taskRow.cpu_percent[1])% | $(Fmt69 $taskRow.after_microseconds_per_input[0]) / $(Fmt69 $taskRow.after_microseconds_per_input[1]) |"}
$taskLines+=@('','Первоначальное замедление ветки игроков в повторе не подтвердилось. У неизвестных мировых надписей повторилось небольшое увеличение затрат: конечный список проверок добавил примерно 0.007 мкс на вход. Поэтому утверждение «дополнительных затрат совсем нет» было бы неверным. Новые переведённые надписи требуют больше работы, чем прежний пропуск перевода. Перевод новых реплик дороже старого пропуска и выполняется при поступлении/обновлении сообщения, а не каждый кадр. Все раунды повтора: PERFORMANCE_0.15.69_RECHECK.json. Игровой FPS не измерен.')
[IO.File]::WriteAllText("$taskProject/translation-source/HUB_NPC_0.15.69_RU.md",($taskLines -join "`n")+"`n",[Text.UTF8Encoding]::new($false))
$taskQA=Get-Content "$taskProject/QA_REPORT.json" -Raw|ConvertFrom-Json
if($taskQA.latest_verified_batch.version -ne '0.15.68-dev'){throw 'Preserve earlier verified milestone'}
$taskQA|Add-Member -NotePropertyName archived_verified_batch_0_15_68 -NotePropertyValue $taskQA.latest_verified_batch
$taskQA.latest_verified_batch=@{version='0.15.69-dev';date='2026-10-15';report='translation-source/HUB_NPC_0.15.69_RU.md';audit='translation-source/HUB_NPC_AUDIT_0.15.69.json';raw_performance='translation-source/PERFORMANCE_0.15.69_RAW.json';jar_entry_scope_proof='translation-source/JAR_SCOPE_0.15.69.json';packaged_gate_root=$CheckRoot;packaged_groups_passed=120;new_npc_assertions=80809;new_exact_lines=83;new_exact_speakers=20;observed_new_source_bodies=53;published_only_variants=30;numeric_receipt_forms=2;choice_labels=4;closed_world_labels=5;observed_variants_replayed=79;observed_unchanged_before=66;observed_unchanged_after=0;catalogue_cards_compared=8937;catalogue_changed_record_ids=@();runtime_dictionary_entries=36044;runtime_tsv_templates=1231;all_hypixel_npcs_translated=$false;overall_goal_complete=$false;all_npc_script_denominators_known=$false;new_frame_hooks=0;new_caches=0;old_frame_context_lore_cache_byte_identical=$true;all_paths_faster=$false;game_fps_measured=$false;zero_fps_impact_proven=$false;installed_modpack_modified=$false;game_started=$false;jar_sha256=$taskHash;jar_bytes=(Get-Item -LiteralPath $taskJar).Length;benchmark_root=$BenchmarkRoot;over10percent_cpu_increase_both_orders=$taskFlags}
$taskQA.latest_verified_batch['world_recheck_root']=$taskRecheck.root
$taskQA.latest_verified_batch['raw_recheck']='translation-source/PERFORMANCE_0.15.69_RECHECK.json'
$taskQA.latest_verified_batch['world_unknown_small_extra_cost_confirmed']=$true
[IO.File]::WriteAllText("$taskProject/QA_REPORT.json",($taskQA|ConvertTo-Json -Depth 35)+"`n",[Text.UTF8Encoding]::new($false))
Write-Output "HUB69 finalized: $taskHash; $($taskFlags.Count) double-order timing flags"
